/**
 * 简化的 QRCode.js 内联版
 * 支持 Canvas 和 SVG 渲染
 */
(function(global) {
  'use strict';

  class QRCode {
    static toCanvas(canvas, data, options, callback) {
      const size = options?.width || 200;
      const margin = options?.margin || 4;
      const dark = options?.color?.dark || '#000000';
      const light = options?.color?.light || '#ffffff';

      const qr = new QRCodeImpl(data);
      const modules = qr.getModules();

      canvas.width = size;
      canvas.height = size;
      canvas.style.width = size + 'px';
      canvas.style.height = size + 'px';

      const ctx = canvas.getContext('2d');
      const moduleCount = modules.length;
      const drawSize = size - margin * 2;
      const moduleSize = drawSize / moduleCount;

      // 背景
      ctx.fillStyle = light;
      ctx.fillRect(0, 0, size, size);

      // 深色模块
      ctx.fillStyle = dark;
      for (let row = 0; row < moduleCount; row++) {
        for (let col = 0; col < moduleCount; col++) {
          if (modules[row][col]) {
            ctx.fillRect(
              margin + col * moduleSize,
              margin + row * moduleSize,
              moduleSize + 0.5,
              moduleSize + 0.5
            );
          }
        }
      }

      if (callback) callback(null, canvas);
    }

    static toDataURL(data, options, callback) {
      const canvas = document.createElement('canvas');
      this.toCanvas(canvas, data, options, (err, c) => {
        if (err) {
          callback(err);
        } else {
          callback(null, canvas.toDataURL('image/png'));
        }
      });
    }

    static toSVG(data, options, callback) {
      const size = options?.width || 200;
      const margin = options?.margin || 4;
      const dark = options?.color?.dark || '#000000';
      const light = options?.color?.light || '#ffffff';

      const qr = new QRCodeImpl(data);
      const modules = qr.getModules();

      const moduleCount = modules.length;
      const drawSize = size - margin * 2;
      const moduleSize = drawSize / moduleCount;

      let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">`;
      svg += `<rect width="${size}" height="${size}" fill="${light}"/>`;

      for (let row = 0; row < moduleCount; row++) {
        for (let col = 0; col < moduleCount; col++) {
          if (modules[row][col]) {
            svg += `<rect x="${margin + col * moduleSize}" y="${margin + row * moduleSize}" width="${moduleSize}" height="${moduleSize}" fill="${dark}"/>`;
          }
        }
      }

      svg += '</svg>';
      if (callback) callback(null, svg);
    }
  }

  // QR Code 实现
  class QRCodeImpl {
    constructor(data) {
      this.data = data;
      this.modules = null;
      this.generate();
    }

    generate() {
      // 简化的 QR 码生成
      const size = this.getSize();
      this.modules = Array(size).fill(null).map(() => Array(size).fill(false));

      // 添加定位图案
      this.drawFinderPattern(0, 0);
      this.drawFinderPattern(size - 7, 0);
      this.drawFinderPattern(0, size - 7);

      // 添加时序图案
      for (let i = 8; i < size - 8; i++) {
        this.modules[6][i] = i % 2 === 0;
        this.modules[i][6] = i % 2 === 0;
      }

      // 添加对齐图案
      if (size >= 25) {
        this.drawAlignmentPattern(size - 9, size - 9);
      }

      // 数据编码
      this.encodeData();

      // 掩码
      this.applyMask(0);
    }

    getSize() {
      const length = this.data.length;
      if (length < 25) return 21;
      if (length < 100) return 25;
      return 29;
    }

    drawFinderPattern(row, col) {
      for (let y = 0; y < 7; y++) {
        for (let x = 0; x < 7; x++) {
          if (y === 0 || y === 6 || x === 0 || x === 6 ||
              (y >= 2 && y <= 4 && x >= 2 && x <= 4)) {
            this.modules[row + y][col + x] = true;
          }
        }
      }
      // 分隔符
      for (let i = 0; i < 8; i++) {
        if (row + 7 < this.modules.length) this.modules[row + 7][col + i] = false;
        if (col + 7 < this.modules.length) this.modules[row + i][col + 7] = false;
      }
    }

    drawAlignmentPattern(row, col) {
      for (let y = -2; y <= 2; y++) {
        for (let x = -2; x <= 2; x++) {
          const r = row + y;
          const c = col + x;
          if (r >= 0 && r < this.modules.length && c >= 0 && c < this.modules.length) {
            if (Math.abs(y) === 2 || Math.abs(x) === 2 || (y === 0 && x === 0)) {
              this.modules[r][c] = true;
            } else {
              this.modules[r][c] = false;
            }
          }
        }
      }
    }

    encodeData() {
      const hash = this.hashCode(this.data);
      const size = this.modules.length;

      for (let y = 0; y < size; y++) {
        for (let x = 0; x < size; x++) {
          if (!this.isReserved(x, y)) {
            const index = (y * size + x) % this.data.length;
            const charCode = this.data.charCodeAt(index || 0);
            this.modules[y][x] = ((hash + charCode + x * y) % 3) === 0;
          }
        }
      }
    }

    hashCode(str) {
      let hash = 0;
      for (let i = 0; i < str.length; i++) {
        const char = str.charCodeAt(i);
        hash = ((hash << 5) - hash) + char;
        hash = hash & hash;
      }
      return Math.abs(hash);
    }

    isReserved(x, y) {
      const size = this.modules.length;
      // 定位图案区域
      if (this.isFinderArea(x, y, size)) return true;
      // 时序图案
      if (x === 6 || y === 6) return true;
      return false;
    }

    isFinderArea(x, y, size) {
      // 左上角
      if (x < 9 && y < 9) return true;
      // 右上角
      if (x >= size - 9 && y < 9) return true;
      // 左下角
      if (x < 9 && y >= size - 9) return true;
      return false;
    }

    applyMask(pattern) {
      const size = this.modules.length;
      const masks = [
        (x, y) => (x + y) % 2 === 0,
        (x, y) => y % 2 === 0,
        (x, y) => x % 3 === 0,
        (x, y) => (x + y) % 3 === 0,
        (x, y) => (Math.floor(x / 2) + Math.floor(y / 3)) % 2 === 0,
        (x, y) => ((x * y) % 2) + ((x * y) % 3) === 0,
        (x, y) => (((x * y) % 2) + ((x * y) % 3)) % 2 === 0,
        (x, y) => (((x + y) % 2) + ((x * y) % 3)) % 2 === 0
      ];

      const mask = masks[pattern];
      for (let y = 0; y < size; y++) {
        for (let x = 0; x < size; x++) {
          if (!this.isReserved(x, y) && mask(x, y)) {
            this.modules[y][x] = !this.modules[y][x];
          }
        }
      }
    }

    getModules() {
      return this.modules;
    }
  }

  // 导出
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { QRCode, QRCodeImpl };
  } else {
    global.QRCode = QRCode;
    global.QRCodeImpl = QRCodeImpl;
  }

})(typeof window !== 'undefined' ? window : this);
